#include <iostream>
#include <vector>
using namespace std;

int n;
vector<long long> tree, a;

void build(int node, int left, int right) {
    if (left == right) {
        tree[node] = a[left];
        return;
    }
    int mid = (left + right) / 2;
    build(node * 2, left, mid);
    build(node * 2 + 1, mid + 1, right);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

void update(int node, int left, int right, int pos, int value) {
    if (left == right) {
        tree[node] = value;
        return;
    }
    int mid = (left + right) / 2;
    if (pos <= mid) update(node * 2, left, mid, pos, value);
    else update(node * 2 + 1, mid + 1, right, pos, value);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

long long query(int node, int left, int right, int ql, int qr) {
    if (qr < left || right < ql) return 0;
    if (ql <= left && right <= qr) return tree[node];
    int mid = (left + right) / 2;
    return query(node * 2, left, mid, ql, qr) + query(node * 2 + 1, mid + 1, right, ql, qr);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> n >> q;
    a.assign(n, 0);
    for (int i = 0; i < n; ++i) cin >> a[i];
    tree.assign(4 * n, 0);
    build(1, 0, n - 1);
    while (q--) {
        int type, x, y;
        cin >> type >> x >> y;
        if (type == 1) update(1, 0, n - 1, x, y);
        else cout << query(1, 0, n - 1, x, y) << '\n';
    }
    return 0;
}
